// ── BodyDiagram component ─────────────────────────────────────────────────────
export default function BodyDiagram({
  primaryMuscles   = [],
  secondaryMuscles = [],
  primaryCounts    = {},   // { chest: 3, biceps: 1 } for intensity
  secondaryCounts  = {},
  onMuscleClick,
  hoveredMuscle,
  size = 'normal',   // 'normal' | 'small' | 'large'
}) {
  const scales = { small: 0.18, normal: 0.24, large: 0.32 };
  const sc = scales[size] || 0.24;

  const getState = (key) => {
    if (primaryMuscles.includes(key))   return 'primary';
    if (secondaryMuscles.includes(key)) return 'secondary';
    if (hoveredMuscle === key)          return 'hover';
    return null;
  };

  // Intensity-based opacity: 1=faint, 2=medium, 3+=full
  const getIntensityColor = (key, type) => {
    const count = type === 'primary' ? (primaryCounts[key] || 0) : (secondaryCounts[key] || 0);
    if (count === 0) return null;
    if (type === 'primary') {
      if (count === 1) return 'rgba(255,107,53,0.35)';
      if (count === 2) return 'rgba(255,107,53,0.65)';
      return 'rgba(255,107,53,0.92)';
    } else {
      if (count === 1) return 'rgba(232,255,0,0.25)';
      if (count === 2) return 'rgba(232,255,0,0.50)';
      return 'rgba(232,255,0,0.80)';
    }
  };

  return (
    <div style={{ display:'flex', flexDirection:'column', alignItems:'center', gap:8 }}>
      {!onMuscleClick && <DiagramLegend />}
      <div style={{ display:'flex', gap:12, alignItems:'flex-start', justifyContent:'center', flexWrap:'wrap' }}>
        <MuscleSVG
          label="Front"
          base={FRONT_BASE}
          overlays={FRONT_OVERLAYS}
          dims={FRONT_DIMS}
          scale={sc}
          getState={getState}
          onMuscleClick={onMuscleClick}
          primaryCounts={primaryCounts}
          secondaryCounts={secondaryCounts}
          getIntensityColor={getIntensityColor}
        />
        <MuscleSVG
          label="Back"
          base={BACK_BASE}
          overlays={BACK_OVERLAYS}
          dims={BACK_DIMS}
          scale={sc}
          getState={getState}
          onMuscleClick={onMuscleClick}
          primaryCounts={primaryCounts}
          secondaryCounts={secondaryCounts}
          getIntensityColor={getIntensityColor}
        />
      </div>
    </div>
  );
}

function MuscleSVG({ label, base, overlays, dims, scale, getState, onMuscleClick, primaryCounts={}, secondaryCounts={}, getIntensityColor }) {
  const [w, h] = dims;
  const dw = Math.round(w * scale);
  const dh = Math.round(h * scale);

  return (
    <div>
      <div style={{ textAlign:'center', fontSize:9, letterSpacing:2, textTransform:'uppercase', color:'var(--text3)', marginBottom:4 }}>
        {label}
      </div>
      <svg
        width={dw} height={dh}
        viewBox={`0 0 ${w} ${h}`}
        xmlns="http://www.w3.org/2000/svg"
        style={{ border:'1px solid var(--border)', borderRadius:8, display:'block' }}
      >
        {/* Body background */}
        <g dangerouslySetInnerHTML={{ __html: base }} />

        {/* Muscle overlays */}
        {Object.entries(overlays).map(([key, pathsHtml]) => {
          const st = getState(key);
          const fill   = st==='primary'   ? 'rgba(255,107,53,0.80)'
                       : st==='secondary' ? 'rgba(232,255,0,0.55)'
                       : st==='hover'     ? 'rgba(255,255,255,0.18)'
                       : 'transparent';
          const stroke = st==='primary'   ? '#ff8050'
                       : st==='secondary' ? '#c8d800'
                       : st==='hover'     ? 'rgba(255,255,255,0.5)'
                       : 'transparent';
          const sw     = st ? 1.5 : 0;

          // Use intensity color if counts provided, otherwise use state color
          const hasCounts = Object.keys(primaryCounts).length > 0 || Object.keys(secondaryCounts).length > 0;
          let intensityFill = fill, intensityStroke = stroke;
          if (hasCounts && st !== 'hover') {
            const primaryIntensity   = getIntensityColor(key, 'primary');
            const secondaryIntensity = getIntensityColor(key, 'secondary');
            if (primaryIntensity)   { intensityFill = primaryIntensity; intensityStroke = '#ff8050'; }
            else if (secondaryIntensity) { intensityFill = secondaryIntensity; intensityStroke = '#c8d800'; }
            else { intensityFill = 'transparent'; intensityStroke = 'transparent'; }
          }

          return (
            <g
              key={key}
              onClick={() => onMuscleClick && onMuscleClick(key)}
              style={{ cursor: onMuscleClick ? 'pointer' : 'default' }}
              dangerouslySetInnerHTML={{
                __html: pathsHtml.replace(
                  /<path/g,
                  `<path style="fill:${intensityFill};stroke:${intensityStroke};stroke-width:${sw}px;transition:fill 0.15s,stroke 0.15s"`
                )
              }}
            />
          );
        })}
      </svg>
    </div>
  );
}

function DiagramLegend() {
  return (
    <div style={{ display:'flex', gap:16, justifyContent:'center', alignItems:'center' }}>
      {[
        ['rgba(255,107,53,0.80)', '#ff8050', 'Primary'],
        ['rgba(232,255,0,0.55)',  '#c8d800', 'Secondary'],
      ].map(([bg, br, label]) => (
        <div key={label} style={{ display:'flex', alignItems:'center', gap:6 }}>
          <div style={{ width:12, height:12, borderRadius:3, background:bg, border:`1.5px solid ${br}`, flexShrink:0 }} />
          <span style={{ fontSize:11, color:'var(--text2)' }}>{label}</span>
        </div>
      ))}
    </div>
  );
}
